package com.alpharip.staffmod.cases.detectioncaseautolinker; import java.util.*; public final class DetectionLinkService {private final LinkedHashMap<String,DetectionRecord> cases=new LinkedHashMap<String,DetectionRecord>();private final LinkedHashMap<String,DetectionLink> links=new LinkedHashMap<String,DetectionLink>();private final LinkedHashSet<String> keys=new LinkedHashSet<String>();public synchronized boolean addCase(DetectionRecord c){if(c==null||cases.containsKey(c.getId()))return false;cases.put(c.getId(),c);auto(c);return true;}public synchronized void setRequiredKeys(Collection<String> v){keys.clear();if(v!=null)for(String k:v)if(k!=null&&!k.trim().isEmpty())keys.add(k.trim());links.clear();for(DetectionRecord c:cases.values())auto(c);}private void auto(DetectionRecord c){if(keys.isEmpty())return;for(DetectionRecord o:cases.values()){if(o.getId().equals(c.getId()))continue;boolean ok=true;for(String k:keys){String a=c.getAttributes().get(k),b=o.getAttributes().get(k);if(a==null||b==null||!a.equalsIgnoreCase(b)){ok=false;break;}}if(ok){DetectionLink l=new DetectionLink(c.getId(),o.getId(),join(),System.currentTimeMillis());links.put(l.getFirstId()+"|"+l.getSecondId(),l);}}}private String join(){StringBuilder b=new StringBuilder();for(String k:keys){if(b.length()>0)b.append(", ");b.append(k);}return b.toString();}public synchronized List<DetectionRecord> getCases(){return Collections.unmodifiableList(new ArrayList<DetectionRecord>(cases.values()));}public synchronized List<DetectionLink> getLinks(){return Collections.unmodifiableList(new ArrayList<DetectionLink>(links.values()));}public synchronized Set<String> getRequiredKeys(){return Collections.unmodifiableSet(new LinkedHashSet<String>(keys));}public synchronized boolean removeCase(String id){if(cases.remove(id)==null)return false;Iterator<DetectionLink> i=links.values().iterator();while(i.hasNext()){DetectionLink l=i.next();if(l.getFirstId().equals(id)||l.getSecondId().equals(id))i.remove();}return true;}public synchronized boolean replaceAll(List<DetectionRecord> v){cases.clear();links.clear();if(v!=null)for(DetectionRecord c:v)if(c!=null&&!cases.containsKey(c.getId()))cases.put(c.getId(),c);for(DetectionRecord c:cases.values())auto(c);return true;}}